    'Serve pages without PHP' => 'Seiten ohne PHP ausliefern',
    'Service ID' => 'Service-ID',
    'Set generateTransformsBeforePageLoad to true in config/general.php, so cached pages link to finished image transforms.' => 'Setzen Sie generateTransformsBeforePageLoad in config/general.php auf true, damit gecachte Seiten fertige Bildtransformationen verlinken.',
    'Set in config/speedy.php' => 'In config/speedy.php gesetzt',
